// app_router.dart
import 'package:auto_route/auto_route.dart';
import 'package:flutter/material.dart';

// 1. 페이지 위젯 정의 (실제 파일은 lib/screens/ 에 위치한다고 가정)
class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});
  @override
  Widget build(BuildContext context) => const Scaffold(body: Center(child: Text('홈 화면')));
}

class DetailScreen extends StatelessWidget {
  final int itemId;
  const DetailScreen({@pathParam required this.itemId, super.key});
  @override
  Widget build(BuildContext context) => Scaffold(
      appBar: AppBar(title: const Text('상세 화면')),
      body: Center(child: Text('아이템 ID: $itemId'))
  );
}

// 2. 라우터 클래스 정의
@AutoRouter(
  replaceInRouteName: 'Screen,Route',
)
class AppRouter extends _$AppRouter {
  AppRouter({super.navigatorKey});

  @override
  List<AutoRoute> get routes => [
    // 초기 경로 설정 (path: '/')
    AutoRoute(page: HomeRoute.page, path: '/', initial: true),
    // 동적 경로 설정 (path: '/detail/:itemId')
    AutoRoute(page: DetailRoute.page, path: '/detail/:itemId'),
  ];
}

// main.dart
import 'package:flutter/material.dart';
import 'router/app_router.dart'; // 2단계에서 정의한 파일
import 'router/app_router.gr.dart'; // 빌드 러너가 생성할 파일

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  // 라우터 인스턴스 생성
  final _appRouter = AppRouter();

  MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp.router(
      title: 'AutoRoute Demo',
      // 라우터 설정
      routerDelegate: _appRouter.delegate(),
      routeInformationParser: _appRouter.defaultRouteParser(),
      // 디버그 배너 제거 등 기타 설정
      debugShowCheckedModeBanner: false,
    );
  }
}

// HomeScreen 위젯 업데이트
import 'package:auto_route/auto_route.dart';
import 'package:flutter/material.dart';
import 'app_router.gr.dart'; // 생성된 라우트 파일 임포트

class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('홈 화면')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            const Text('홈 화면'),
            const SizedBox(height: 20),
            ElevatedButton(
              onPressed: () {
                // 타입 안전한 네비게이션: DetailRoute 클래스 사용
                context.router.push(
                  DetailRoute(itemId: 123) // itemId는 필수 인자
                );
              },
              child: const Text('상세 페이지로 이동 (ID: 123)'),
            ),
          ],
        ),
      ),
    );
  }
}

// auth_guard.dart
import 'package:auto_route/auto_route.dart';
import 'app_router.gr.dart'; // HomeRoute 접근을 위해 필요

class AuthGuard extends AutoRouteGuard {
  final bool isAuthenticated; // 실제로는 Provider나 Bloc에서 가져옴

  AuthGuard({this.isAuthenticated = false});

  @override
  void onNavigation(NavigationResolver resolver, StackRouter router) {
    if (isAuthenticated) {
      // 인증됨: 요청된 경로로 이동을 허용
      resolver.next(true);
    } else {
      // 인증되지 않음: 홈 화면으로 리다이렉트
      // resolver.redirect(LoginRoute()); // 실제로는 로그인 페이지로 리다이렉트
      router.push(const HomeRoute()); // 예시를 위해 홈으로 리다이렉트
      resolver.next(false); // 요청된 경로로의 이동은 취소
    }
  }
}

// app_router.dart (업데이트)
// ... 기존 코드 ...

// AuthGuard 인스턴스 생성 (isAuthenticated: false로 설정)
final authGuard = AuthGuard(isAuthenticated: false);

@AutoRouter(
  replaceInRouteName: 'Screen,Route',
)
class AppRouter extends _$AppRouter {
  AppRouter({super.navigatorKey});

  @override
  List<AutoRoute> get routes => [
    AutoRoute(page: HomeRoute.page, path: '/', initial: true),
    // DetailRoute에 AuthGuard 적용
    AutoRoute(
      page: DetailRoute.page,
      path: '/detail/:itemId',
      guards: [authGuard], // 가드 추가
    ),
  ];
}
